CREATE TABLE oag_can_policies(policy_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),policy_version INTEGER NOT NULL,effective_from TEXT NOT NULL,effective_until TEXT,root_activation_rule TEXT NOT NULL,responsibility_confirmation_rule TEXT NOT NULL,delegation_confirmation_rule TEXT NOT NULL,max_delegation_depth INTEGER NOT NULL CHECK(max_delegation_depth=1),proof_validity_rule TEXT NOT NULL,graph_supersession_rule TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_actor_bindings(binding_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),actor_id TEXT NOT NULL,principal_id TEXT NOT NULL REFERENCES oir_principals(principal_id),membership_id TEXT NOT NULL REFERENCES oir_organization_memberships(membership_id),tenant_id TEXT NOT NULL REFERENCES oir_tenants(tenant_id),company_id TEXT NOT NULL REFERENCES oir_companies(company_id),effective_from TEXT NOT NULL,policy_id TEXT NOT NULL REFERENCES oag_can_policies(policy_id),binding_reference TEXT NOT NULL,causal_references_json TEXT NOT NULL,UNIQUE(actor_id,principal_id,membership_id,tenant_id,company_id));
CREATE TABLE oag_can_positions(position_version_id TEXT PRIMARY KEY,position_id TEXT NOT NULL,actor_id TEXT NOT NULL,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,position_code TEXT NOT NULL,position_title TEXT NOT NULL,effective_from TEXT NOT NULL,effective_until TEXT,causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_responsibilities(responsibility_id TEXT PRIMARY KEY,declaration_version_id TEXT NOT NULL UNIQUE,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,subject_actor_id TEXT NOT NULL,scope_json TEXT NOT NULL,effective_from TEXT NOT NULL,effective_until TEXT,lifecycle_state TEXT NOT NULL CHECK(lifecycle_state IN('DECLARED','ACTIVE')),confirmation_chain_id TEXT,policy_id TEXT NOT NULL REFERENCES oag_can_policies(policy_id),causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_roots(root_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,actor_id TEXT NOT NULL,actor_binding_id TEXT NOT NULL REFERENCES oag_can_actor_bindings(binding_id),principal_id TEXT NOT NULL,membership_id TEXT NOT NULL,domain TEXT NOT NULL,scope_json TEXT NOT NULL,effective_from TEXT NOT NULL,effective_until TEXT,bootstrap_eligibility_id TEXT NOT NULL UNIQUE REFERENCES orpa_eligibilities(eligibility_id),bootstrap_authority_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,company_binding_id TEXT NOT NULL,policy_id TEXT NOT NULL REFERENCES oag_can_policies(policy_id),graph_version_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_confirmation_chains(chain_id TEXT PRIMARY KEY,subject_actor_id TEXT NOT NULL,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,declaration_version_id TEXT NOT NULL,steps_json TEXT NOT NULL,terminal_scope_json TEXT NOT NULL,graph_version_id TEXT NOT NULL,authority_source_id TEXT NOT NULL,authority_source_actor_id TEXT NOT NULL,subject_fact_id TEXT NOT NULL,policy_id TEXT NOT NULL REFERENCES oag_can_policies(policy_id),effective_from TEXT NOT NULL,effective_until TEXT,evidence_references_json TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_delegations(delegation_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,source_authority_id TEXT NOT NULL,source_actor_id TEXT NOT NULL,target_actor_id TEXT NOT NULL,target_actor_binding_id TEXT NOT NULL REFERENCES oag_can_actor_bindings(binding_id),domain TEXT NOT NULL,scope_json TEXT NOT NULL,effective_from TEXT NOT NULL,effective_until TEXT NOT NULL,depth INTEGER NOT NULL CHECK(depth=1),confirmation_chain_id TEXT NOT NULL REFERENCES oag_can_confirmation_chains(chain_id),policy_id TEXT NOT NULL REFERENCES oag_can_policies(policy_id),graph_version_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_graph_versions(graph_version_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,policy_id TEXT NOT NULL REFERENCES oag_can_policies(policy_id),graph_digest TEXT NOT NULL UNIQUE,effective_from TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE oag_can_graph_references(graph_version_id TEXT NOT NULL REFERENCES oag_can_graph_versions(graph_version_id),kind TEXT NOT NULL,identity TEXT NOT NULL,semantic_digest TEXT NOT NULL,PRIMARY KEY(graph_version_id,kind,identity));
CREATE TABLE oag_can_transitions(transition_id TEXT PRIMARY KEY,subject_kind TEXT NOT NULL,subject_id TEXT NOT NULL,transition_kind TEXT NOT NULL CHECK(transition_kind IN('REVOKED','SUPERSEDED','INVALIDATED')),successor_id TEXT,transitioned_at TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,UNIQUE(subject_kind,subject_id));
CREATE TABLE oag_can_audit_events(audit_event_id TEXT PRIMARY KEY,event_kind TEXT NOT NULL,subject_kind TEXT NOT NULL,subject_id TEXT NOT NULL,outcome TEXT NOT NULL,reason_code TEXT,actor_id TEXT,policy_id TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,recorded_at TEXT NOT NULL,content_payload TEXT CHECK(content_payload IS NULL));
CREATE INDEX idx_oag_can_graph_context ON oag_can_graph_versions(tenant_id,company_id);
CREATE INDEX idx_oag_can_transition_subject ON oag_can_transitions(subject_kind,subject_id);
CREATE TRIGGER oag_can_policy_no_update BEFORE UPDATE ON oag_can_policies BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_binding_no_update BEFORE UPDATE ON oag_can_actor_bindings BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_position_no_update BEFORE UPDATE ON oag_can_positions BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_root_no_update BEFORE UPDATE ON oag_can_roots BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_responsibility_no_update BEFORE UPDATE ON oag_can_responsibilities BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_confirmation_no_update BEFORE UPDATE ON oag_can_confirmation_chains BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_delegation_no_update BEFORE UPDATE ON oag_can_delegations BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_graph_no_update BEFORE UPDATE ON oag_can_graph_versions BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_transition_no_update BEFORE UPDATE ON oag_can_transitions BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_audit_no_update BEFORE UPDATE ON oag_can_audit_events BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_policy_no_delete BEFORE DELETE ON oag_can_policies BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_binding_no_delete BEFORE DELETE ON oag_can_actor_bindings BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_position_no_delete BEFORE DELETE ON oag_can_positions BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_root_no_delete BEFORE DELETE ON oag_can_roots BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_responsibility_no_delete BEFORE DELETE ON oag_can_responsibilities BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_confirmation_no_delete BEFORE DELETE ON oag_can_confirmation_chains BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_delegation_no_delete BEFORE DELETE ON oag_can_delegations BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_graph_no_delete BEFORE DELETE ON oag_can_graph_versions BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_transition_no_delete BEFORE DELETE ON oag_can_transitions BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
CREATE TRIGGER oag_can_audit_no_delete BEFORE DELETE ON oag_can_audit_events BEGIN SELECT RAISE(ABORT,'OAG_CAN_IMMUTABLE'); END;
